CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own role" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE FUNCTION public.assign_verified_price_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF new.email_confirmed_at IS NOT NULL AND lower(new.email) = 'eshoesole@gmail.com' THEN INSERT INTO public.user_roles(user_id, role) VALUES(new.id, 'admin') ON CONFLICT DO NOTHING; END IF; RETURN new; END; $$;
CREATE TRIGGER price_owner_on_create AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_verified_price_owner();
CREATE TRIGGER price_owner_on_confirm AFTER UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_verified_price_owner();
CREATE TABLE public.product_prices (piece_id text PRIMARY KEY CHECK (piece_id IN ('01','02','03','04','05','06','07')), amount numeric(12,2) NOT NULL CHECK (amount >= 0));
GRANT SELECT ON public.product_prices TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON public.product_prices TO authenticated;
GRANT ALL ON public.product_prices TO service_role;
ALTER TABLE public.product_prices ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public prices" ON public.product_prices FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Owner inserts prices" ON public.product_prices FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Owner updates prices" ON public.product_prices FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Owner removes prices" ON public.product_prices FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));